//! Tests for environ support
//!
//! These tests verify that rlibc-x2 properly exports the `environ` symbol
//! needed by Rust's std::env module.

use std::ffi::CStr;

/// Test that environ symbol is exported and accessible
#[test]
fn environ_is_not_null() {
    // Access environ from rlibc_x2
    // This should be set during program startup
    let env_ptr = unsafe { rlibc_x2::environ };
    assert!(!env_ptr.is_null(), "environ should not be null after startup");
}

/// Test that we can read at least one environment variable
#[test]
fn environ_has_entries() {
    let env_ptr = unsafe { rlibc_x2::environ };
    assert!(!env_ptr.is_null());

    // There should be at least one environment variable
    let first_entry = unsafe { *env_ptr };
    assert!(
        !first_entry.is_null(),
        "environ should have at least one entry"
    );
}

/// Test that PATH is typically present (common sanity check)
#[test]
fn environ_contains_path() {
    let env_ptr = unsafe { rlibc_x2::environ };
    assert!(!env_ptr.is_null());

    let mut found_path = false;
    let mut current = env_ptr;

    unsafe {
        while !(*current).is_null() {
            let entry = CStr::from_ptr(*current);
            if let Ok(s) = entry.to_str() {
                if s.starts_with("PATH=") {
                    found_path = true;
                    break;
                }
            }
            current = current.add(1);
        }
    }

    assert!(found_path, "PATH environment variable should be present");
}

