fn integration_test_environ() {
    // Build the test binary
    let status = Command::new("cargo")
        .args(["build", "-p", "test-environ"])
        .status()
        .expect("failed to build");
    assert!(status.success());

    // Run it
    let output = Command::new("target/debug/test-environ")
        .output()
        .expect("failed to run");

    assert!(output.status.success(), "test-environ failed with code {:?}", output.status.code());
}
```

So `cargo test` = everything, `cargo test -p rlibc-x2-tests environ` = just environ integration tests.

