//!
//! Provides the `environ` symbol needed by std::env.

use core::ffi::c_char;

/// Global environment pointer - set during startup by __libc_start_main
#[unsafe(no_mangle)]
pub static mut environ: *const *const c_char = core::ptr::null();

/// Initialize environ from the environment pointer passed to __libc_start_main
pub fn init(envp: *const *const c_char) {
    unsafe {
        environ = envp;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn environ_symbol_exists() {
        // Just verify the symbol exists and has the right type
        let _: *const *const c_char = unsafe { environ };
    }
}

