//! Environment variable support
//!
//! Provides the `environ` symbol and `getenv` function needed by std::env.

use core::ffi::c_char;
use crate::errno::strlen;

/// Global environment pointer - set during startup by __libc_start_main
#[unsafe(no_mangle)]
pub static mut environ: *const *const c_char = core::ptr::null();

/// Initialize environ from the environment pointer passed to __libc_start_main
pub fn init(envp: *const *const c_char) {
    unsafe {
        environ = envp;
    }
}

/// Get an environment variable by name
/// Returns pointer to the value (after '=') or null if not found
#[unsafe(no_mangle)]
pub extern "C" fn getenv(name: *const c_char) -> *const c_char {
    if name.is_null() {
        return core::ptr::null();
    }

    let name_len = unsafe { strlen(name as *const u8) };
    if name_len == 0 {
        return core::ptr::null();
    }

    unsafe {
        let mut current = environ;
        if current.is_null() {
            return core::ptr::null();
        }

        while !(*current).is_null() {
            let entry = *current;

            // Check if entry starts with "name="
            let mut matches = true;
            for i in 0..name_len {
                if *entry.add(i) != *name.add(i) {
                    matches = false;
                    break;
                }
            }

            // Check for '=' after the name
            if matches && *entry.add(name_len) == b'=' as c_char {
                // Return pointer to value (after '=')
                return entry.add(name_len + 1);
            }

            current = current.add(1);
        }
    }

    core::ptr::null()
}

