Valid concern. The reality is libc functions are inherently unsafe:
- C ABI = raw pointers
- `environ` = global mutable state
- No ownership semantics at the boundary

But we can **minimize and encapsulate** unsafe:

```rust
/// Safe iterator over environ entries
fn iter_environ() -> impl Iterator<Item = &'static CStr> {
    struct EnvIter(*const *const c_char);

    impl Iterator for EnvIter {
        type Item = &'static CStr;
        fn next(&mut self) -> Option<Self::Item> {
            unsafe {
                if self.0.is_null() || (*self.0).is_null() {
                    return None;
                }
                let entry = CStr::from_ptr(*self.0);
                self.0 = self.0.add(1);
                Some(entry)
            }
        }
    }

    EnvIter(unsafe { environ })
}

/// getenv implementation using safe iterator
#[unsafe(no_mangle)]
pub extern "C" fn getenv(name: *const c_char) -> *const c_char {
    let name = unsafe { CStr::from_ptr(name) };  // one unsafe

    for entry in iter_environ() {  // safe iteration
        if let Some(value) = entry.to_bytes().strip_prefix(name.to_bytes()) {
            if value.first() == Some(&b'=') {
                return value[1..].as_ptr() as *const c_char;
            }
        }
    }
    core::ptr::null()
}
```

Pattern: **unsafe at boundaries, safe logic internally**.

Want me to implement it this way?

