    if env_ptr.is_null() {
        eprintln!("FAIL: environ is null");
        return ExitCode::from(1);
    }

    // Test 2: environ should have at least one entry
    let first_entry = unsafe { *env_ptr };
    if first_entry.is_null() {
        eprintln!("FAIL: environ has no entries");
